mapper.select:
SELECT d.id AS document_id, 'DUPLICATE' AS code, o.knowledge_base_id, kb.name AS knowledge_base_name, o.id AS other_document_id, o.filename FROM document d JOIN document o ON o.tenant_id = d.tenant_id AND o.sha256 = d.sha256 AND o.id <> d.id AND o.status = 'READY' JOIN knowledge_base kb ON kb.id = o.knowledge_base_id WHERE d.tenant_id = #{tenantId} AND d.id IN #{id}
UNION ALL SELECT d.id, 'NEAR_DUPLICATE', o.knowledge_base_id, kb.name, o.id, o.filename FROM document d JOIN document_overlap ov ON ov.document_id = d.id JOIN document o ON o.id = ov.other_document_id AND o.sha256 <> d.sha256 AND o.status = 'READY' JOIN knowledge_base kb ON kb.id = o.knowledge_base_id WHERE d.tenant_id = #{tenantId} AND d.id IN #{id}
ORDER BY 1, 5

SELECT d.id, d.knowledge_base_id, kb.name AS knowledge_base_name, d.filename, d.expires_on, CASE WHEN THEN 'EXPIRED' ELSE 'EXPIRING' END AS validity FROM document d JOIN knowledge_base kb ON kb.id = d.knowledge_base_id WHERE d.tenant_id = #{tenantId} AND (() OR ())
AND d.knowledge_base_id IN ()
ORDER BY d.expires_on, d.id LIMIT #{limit}
